 color:#fff;font-size:10px;padding:5px 6px;
}
#dlg .dbody{padding:16px 14px 14px;font-size:8px;color:#000;display:flex;flex-direction:column;gap:12px}
#dlg .big{font-size:14px;color:#000080}
#dlg button{
 font-family:inherit;font-size:10px;
 background:#c0c0c0;color:#000;
 border:3px solid;border-color:#fff #404040 #404040 #fff;
 padding:8px 14px;cursor:pointer;min-width:150px;
}
#dlg button:active{border-color:#404040 #fff #fff #404040}
#dlg button:focus{outline:1px dotted #000;outline-offset:-5px}
.hint{font-size:7px;color:#404040;line-height:1.9}
</style>
